<?php use VazinCMS\Security; ?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark"><title>مدیریت Vazin CMS</title><link rel="stylesheet" href="/assets/app.css"><script src="https://telegram.org/js/telegram-web-app.js"></script></head><body><main class="auth"><div class="logo">V</div><h1><?=Security::e(is_array($connection)?'مدیریت '.$connection['name']:'Web App در دسترس نیست')?></h1><p id="telegram-status"><?=is_array($connection)?'در حال تأیید هویت Telegram…':'این اتصال فعال نیست.'?></p></main><?php if(is_array($connection)):?><script nonce="<?=Security::e(Security::cspNonce())?>">(async()=>{const status=document.getElementById('telegram-status');const tg=window.Telegram&&window.Telegram.WebApp;if(!tg||!tg.initData){status.textContent='این صفحه را از منوی ربات Telegram باز کنید.';return}tg.ready();tg.expand();const body=new URLSearchParams({_csrf:'<?=Security::e(Security::csrf())?>',init_data:tg.initData});try{const response=await fetch('/telegram/webapp/<?=Security::e($connection['webhook_key'])?>/session',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body,credentials:'same-origin'});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.message||'ورود انجام نشد');status.textContent='ورود موفق؛ انتقال به مدیریت…';location.replace(result.redirect||'/admin')}catch(error){status.textContent=error.message||'ورود انجام نشد'}})();</script><?php endif;?></body></html>
